_hip_moe = None   # bound only on ROCm in stock; read only behind _is_hip


def _defer_side_work(self, hidden_states, current_stream):
    """Lever SD: from SD_MIN_ROWS rows the shared expert (alt stream) and the mHC stats (enqueued later, at the
    post) wait for the router; the stats stream is joined back at once (an empty join, capture-safe)."""
    rows = int(hidden_states.shape[0])
    if not levers.SD_MIN_ROWS or rows < levers.SD_MIN_ROWS:
        return
    self.alt_stream.wait_stream(current_stream)
    stats = getattr(self, "dsv4f_stats_stream", None)
    if stats is not None:
        stats.wait_stream(current_stream)
        current_stream.wait_stream(stats)
    if levers.first(f"sd{rows}"):
        levers.announce(f"sd{rows}", "lever SD: side work after the router")


def forward_normal_dual_stream(
    self,
    hidden_states: torch.Tensor,
    gemm_output_zero_allocator: BumpAllocator = None,
    input_ids: Optional[torch.Tensor] = None,
    input_ids_global: Optional[torch.Tensor] = None,
    num_token_non_padded: Optional[torch.Tensor] = None,
    use_vision_topk: bool = False,
    return_moe_output: bool = False,
) -> Union[torch.Tensor, MoEOutput]:
    # Note(kpham-sgl): issue order satisfies 3 constraints:
    # - no stream explosion: main (routed) issued before alt block -> capture reuses 1 alt stream;
    # - PDL overlap: routed is the last main-stream kernel (fuses w/ residual add);
    # - dispose_tensor: disabled during capture (CaptureFlags.disable_dispose_tensor) so the routed
    #   deep_gemm does not free hidden_states, which the shared expert reads on the alt stream.
    use_flashinfer_trtllm_bypass = get_forward().flashinfer_trtllm_bypass
    current_stream = torch.cuda.current_stream()
    # Quantize-once (SGLANG_OPT_MOE_QUANT_ONCE) must happen on the main
    # stream BEFORE the alt-stream fork so both consumers see it.
    pre_quant_input = (
        None
        if use_flashinfer_trtllm_bypass
        else self._maybe_quant_moe_input_once(hidden_states)
    )
    self.alt_stream.wait_stream(current_stream)
    nq_input = nq.issue(self, hidden_states)   # lever NQ: the routed NVFP4 input quantize on a side stream
    should_quant_routed_input_mxfp8 = (
        not use_flashinfer_trtllm_bypass
        and pre_quant_input is None
        and self._should_quant_routed_input_mxfp8(hidden_states)
    )
    if should_quant_routed_input_mxfp8:
        self.routed_quant_stream.wait_stream(current_stream)
    has_shared_output = (
        hidden_states.shape[0] > 0 and self.num_fused_shared_experts == 0
    )
    dispatch_info = (
        ExpertLocationDispatchInfo.init_new(layer_id=self.layer_id)
        if get_exec().moe.enable_eplb and not self.is_nextn
        else None
    )

    # router_logits: (num_tokens, n_experts)
    if _is_hip:
        router_logits, router_logits_partials = _hip_moe.forward_gate(
            self,
            hidden_states,
            gemm_output_zero_allocator,
            fused_gate=not use_flashinfer_trtllm_bypass and not use_vision_topk,
        )
    else:
        # lever RTR: the router gate GEMM as one kernel, stock's cuBLAS bits (stock's self.gate otherwise)
        router_logits = rtr.gate(self, hidden_states, gemm_output_zero_allocator)
        router_logits_partials = None
    if use_flashinfer_trtllm_bypass:
        topk_output = BypassedTopKOutput(
            hidden_states=hidden_states,
            router_logits=router_logits,
            topk_config=self.topk.topk_config,
        )
    else:
        topk_kwargs = (
            {"input_ids": input_ids_global}
            if getattr(self, "is_hash", False)
            else {}
        )
        if router_logits_partials is not None:
            topk_kwargs["router_logits_partials"] = router_logits_partials
        if use_vision_topk:
            # lever RE5: the fused top-k + E5 when stock would prune, else stock vision_topk
            topk_output = route_e5.route(
                self,
                router_logits,
                input_ids_global,
                num_token_non_padded,
            )
        else:
            topk_output = self.topk(
                hidden_states,
                router_logits,
                num_token_non_padded=num_token_non_padded,
                expert_location_dispatch_info=dispatch_info,
                **topk_kwargs,
            )
    # lever RE5: stock prune_topk, except on the output route_e5.route pruned already
    topk_output = route_e5.after_topk(self, topk_output)
    _defer_side_work(self, hidden_states, current_stream)   # lever SD
    stp_mode = stp.mark(self, hidden_states, pre_quant_input, current_stream)   # lever STP: this call's mode (late / all fork the tail here)
    # Issued after the router so the main chain stays on the main stream at replay.
    routed_pre_quant_input = nq_input if nq_input is not None else pre_quant_input   # lever NQ
    if should_quant_routed_input_mxfp8:
        with torch.cuda.stream(self.routed_quant_stream):
            x_q, x_sf = self.experts.quant_method.quantize_routed_input(
                hidden_states, routed_hidden_size(self.experts)
            )
            ready = self.routed_quant_stream.record_event()
        routed_pre_quant_input = Mxfp8RoutedInputPreQuant(x_q, x_sf, ready)
    supports_deferred_finalize = (
        self.experts.supports_deferred_finalize
        if topk_output.format == TopKOutputFormat.BYPASSED
        else self.experts.supports_routed_deferred_finalize
    )
    deferred_finalize = (
        has_shared_output
        and not self._shared_expert_tp1
        and supports_deferred_finalize
        and (
            self._deferred_finalize_max_tokens <= 0
            or hidden_states.shape[0] <= self._deferred_finalize_max_tokens
        )
    )
    # NOTE: if `return_moe_output`, always try to defer finalize
    deferred_finalize = deferred_finalize or (
        return_moe_output
        and isinstance(self.experts.quant_method, Mxfp4FlashinferTrtllmMoEMethod)
    )
    if deferred_finalize:
        final_hidden_states = self.experts.forward_deferred_finalize(
            hidden_states, topk_output, pre_quant_input=routed_pre_quant_input
        )
    elif use_flashinfer_trtllm_bypass:
        final_hidden_states = self.experts.forward_impl(hidden_states, topk_output)
    elif routed_pre_quant_input is not None:
        final_hidden_states = self.experts(
            hidden_states, topk_output, pre_quant_input=routed_pre_quant_input
        )
    else:
        final_hidden_states = self.experts(hidden_states, topk_output)
    if (
        not _is_cuda
        and not _is_musa
        and not _use_aiter
        or isinstance(self.experts.quant_method, KTEPWrapperMethod)
    ):
        final_hidden_states *= self.routed_scaling_factor

    # Shared expert on alt stream, issued AFTER the main (routed) branch. See note above.
    # Only the quant-once fp8 pair is shared with it; the routed MXFP8 pre-quant is not.
    # lever STP: stock's alt-stream call, or the tail on the top-priority tail stream (joined into the main stream here)
    shared_output = stp.shared(
        self,
        hidden_states,
        gemm_output_zero_allocator,
        pre_quant_input,
        current_stream,
        stp_mode,
    )

    # The routed-input pre-quant was already joined inside the routed MoE apply.
    current_stream.wait_stream(self.alt_stream)

    if deferred_finalize and get_forward().defer_moe_finalize:
        # deferred_finalize excludes _shared_expert_tp1, so the shared add folds in.
        assert shared_output is not None
        from sglang.srt.layers.layer_boundary.fusions.cutedsl import (
            MoeDeferredFinalize,
        )

        return MoeDeferredFinalize.from_flashinfer(
            final_hidden_states,
            gated_shared_output=shared_output,
            m=hidden_states.shape[0],
            reduce=sum_post_experts_output,
        )

    if return_moe_output:
        return MoEOutput(
            routed=final_hidden_states,
            shared=shared_output,
            experts=self.experts,
            routed_scaling_factor=self.routed_scaling_factor,
            shared_is_replicated=self._shared_expert_tp1,
        )

    if deferred_finalize:
        from sglang.srt.layers.moe.moe_runner.flashinfer_trtllm import (
            finalize_flashinfer_trtllm_deferred_output,
        )

        final_hidden_states = finalize_flashinfer_trtllm_deferred_output(
            final_hidden_states,
            shared_output,
        )
    else:
        final_hidden_states = maybe_fuse_routed_scale_and_shared_add(
            self.experts,
            final_hidden_states,
            None if self._shared_expert_tp1 else shared_output,
            self.routed_scaling_factor,
        )
    if self.reduce_results:
        final_hidden_states = post_experts_all_reduce(final_hidden_states)
    # TP1 shared experts are replicated: add them after this block's
    # all-reduce, or on TP rank 0 only when the stage boundary sums.
    if self._shared_expert_tp1 and self._adds_replicated_output():
        final_hidden_states += shared_output
    return final_hidden_states


def forward_normal(
    self,
    hidden_states: torch.Tensor,
    gemm_output_zero_allocator: BumpAllocator = None,
    input_ids: Optional[torch.Tensor] = None,
    input_ids_global: Optional[torch.Tensor] = None,
    skip_shared_experts: bool = False,
    num_token_non_padded: Optional[torch.Tensor] = None,
    use_vision_topk: bool = False,
    return_moe_output: bool = False,
) -> Union[torch.Tensor, MoEOutput]:
    if hasattr(self, "shared_experts") and use_intel_amx_backend(
        self.shared_experts.gate_up_proj
    ):
        return self.forward_cpu(hidden_states)
    dispatch_info = (
        ExpertLocationDispatchInfo.init_new(layer_id=self.layer_id)
        if get_exec().moe.enable_eplb and not self.is_nextn
        else None
    )
    defer_shared = not self.experts.moe_runner_config.inplace
    # PoC (SGLANG_DP_SHARED_EXPERT_LOCAL): shared expert is computed on the LOCAL
    # hidden in the decoder layer (before the dp gather) and added after the
    # reduce_scatterv. When set, never compute/add it here (on the global buffer).
    shared_output = None
    if hidden_states.shape[0] > 0:
        # Quantize-once (SGLANG_OPT_MOE_QUANT_ONCE): only worthwhile when
        # the shared expert also runs here on the same tensor.
        pre_quant_input = (
            None
            if skip_shared_experts
            else self._maybe_quant_moe_input_once(hidden_states)
        )
        if (
            not defer_shared
            and not self._fuse_shared_experts_inside_sbo
            and not skip_shared_experts
        ):
            shared_output = self._forward_shared_experts(
                hidden_states,
                gemm_output_zero_allocator,
                pre_quant_input=pre_quant_input,
            )
        # router_logits: (num_tokens, n_experts)
        if _is_hip:
            router_logits, router_logits_partials = _hip_moe.forward_gate(
                self,
                hidden_states,
                gemm_output_zero_allocator,
                fused_gate=not use_vision_topk,
            )
        else:
            # lever RT: eager EXTEND: the gate's cuBLAS torch.mm without the module / wrapper layers
            router_logits = rt.gate(self, hidden_states, gemm_output_zero_allocator)
            router_logits_partials = None
        topk_kwargs = (
            {"input_ids": input_ids_global}
            if getattr(self, "is_hash", False)
            else {}
        )
        if router_logits_partials is not None:
            topk_kwargs["router_logits_partials"] = router_logits_partials
        if use_vision_topk:
            # lever RE5: the fused top-k + E5 when stock would prune, else stock vision_topk
            # lever RT: eager EXTEND: stock's compiled router kernel launched directly (route_e5.route otherwise)
            topk_output = rt.route(
                self,
                router_logits,
                input_ids_global,
                num_token_non_padded,
            )
        else:
            topk_output = self.topk(
                hidden_states,
                router_logits,
                num_token_non_padded=num_token_non_padded,
                expert_location_dispatch_info=dispatch_info,
                **topk_kwargs,
            )
    else:
        pre_quant_input = None
        shared_output = None
        topk_output = self.topk.empty_topk_output(
            hidden_states.device, layer_id=self.layer_id
        )

    # lever RE5: stock prune_topk, except on the output route_e5.route pruned already
    # lever RT: eager EXTEND (no E5 prune in flight): after_topk's unchanged return taken directly
    topk_output = rt.after_topk(self, topk_output)
    if self._fuse_shared_experts_inside_sbo and not skip_shared_experts:
        shared_output = None

        def _pre_combine_hook(
            dispatcher: BaseDispatcher, combine_input: CombineInput
        ):
            nonlocal shared_output
            self.alt_stream.wait_stream(torch.cuda.current_stream())
            with torch.cuda.stream(self.alt_stream):
                shared_output = self._forward_shared_experts(
                    hidden_states, gemm_output_zero_allocator
                )

            pre_combine_hook_handle.remove()

        def _post_combine_hook(
            dispatcher: BaseDispatcher, hidden_states: torch.Tensor
        ):
            nonlocal shared_output
            torch.cuda.current_stream().wait_stream(self.alt_stream)
            post_combine_hook_handle.remove()

        pre_combine_hook_handle = self.experts.dispatcher.register_pre_combine_hook(
            _pre_combine_hook
        )
        post_combine_hook_handle = (
            self.experts.dispatcher.register_post_combine_hook(_post_combine_hook)
        )

    if pre_quant_input is not None:
        final_hidden_states = self.experts(
            hidden_states,
            topk_output,
            pre_quant_input=pre_quant_input,
        )
    else:
        final_hidden_states = self.experts(
            hidden_states,
            topk_output,
        )
    if (
        not _is_cuda
        and not _is_musa
        and not _is_xpu
        and not _use_aiter
        or isinstance(self.experts.quant_method, KTEPWrapperMethod)
    ):
        # fused in biased_grouped_topk so we can skip here
        final_hidden_states *= self.routed_scaling_factor

    if (
        defer_shared
        and hidden_states.shape[0] > 0
        and not self._fuse_shared_experts_inside_sbo
        and not skip_shared_experts
    ):
        shared_output = self._forward_shared_experts(
            hidden_states,
            gemm_output_zero_allocator,
            pre_quant_input=pre_quant_input,
        )

    if return_moe_output:
        return MoEOutput(
            routed=final_hidden_states,
            shared=shared_output,
            experts=self.experts,
            routed_scaling_factor=self.routed_scaling_factor,
            shared_is_replicated=self._shared_expert_tp1,
        )

    final_hidden_states = maybe_fuse_routed_scale_and_shared_add(
        self.experts,
        final_hidden_states,
        None if self._shared_expert_tp1 else shared_output,
        self.routed_scaling_factor,
    )
    if self.reduce_results:
        final_hidden_states = post_experts_all_reduce(final_hidden_states)
    # TP1 shared experts are replicated: add them after this block's
    # all-reduce, or on TP rank 0 only when the stage boundary sums.
    if (
        shared_output is not None
        and self._shared_expert_tp1
        and self._adds_replicated_output()
    ):
        final_hidden_states += shared_output
    return final_hidden_states


# lever FG (gen_fg.py): forward_normal from the router on, the logits passed in and the post-experts all-reduce left
# to fg.ffn (captured in FG's CUDA graphs at a row bucket); fg_gate = forward_normal's gate call.


def forward_normal_fg(
    self,
    fg_logits: torch.Tensor,
    hidden_states: torch.Tensor,
    gemm_output_zero_allocator: BumpAllocator = None,
    input_ids: Optional[torch.Tensor] = None,
    input_ids_global: Optional[torch.Tensor] = None,
    skip_shared_experts: bool = False,
    num_token_non_padded: Optional[torch.Tensor] = None,
    use_vision_topk: bool = False,
    return_moe_output: bool = False,
) -> Union[torch.Tensor, MoEOutput]:
    if hasattr(self, "shared_experts") and use_intel_amx_backend(
        self.shared_experts.gate_up_proj
    ):
        return self.forward_cpu(hidden_states)
    dispatch_info = (
        ExpertLocationDispatchInfo.init_new(layer_id=self.layer_id)
        if get_exec().moe.enable_eplb and not self.is_nextn
        else None
    )
    defer_shared = not self.experts.moe_runner_config.inplace
    # PoC (SGLANG_DP_SHARED_EXPERT_LOCAL): shared expert is computed on the LOCAL
    # hidden in the decoder layer (before the dp gather) and added after the
    # reduce_scatterv. When set, never compute/add it here (on the global buffer).
    shared_output = None
    if hidden_states.shape[0] > 0:
        # Quantize-once (SGLANG_OPT_MOE_QUANT_ONCE): only worthwhile when
        # the shared expert also runs here on the same tensor.
        pre_quant_input = (
            None
            if skip_shared_experts
            else self._maybe_quant_moe_input_once(hidden_states)
        )
        if (
            not defer_shared
            and not self._fuse_shared_experts_inside_sbo
            and not skip_shared_experts
        ):
            shared_output = self._forward_shared_experts(
                hidden_states,
                gemm_output_zero_allocator,
                pre_quant_input=pre_quant_input,
            )
        # router_logits: (num_tokens, n_experts)
        if _is_hip:
            router_logits, router_logits_partials = _hip_moe.forward_gate(
                self,
                hidden_states,
                gemm_output_zero_allocator,
                fused_gate=not use_vision_topk,
            )
        else:
            # lever RT: eager EXTEND: the gate's cuBLAS torch.mm without the module / wrapper layers
            router_logits = fg_logits   # lever FG: the eager gate GEMM's fp32 logits (FG's static buffer)
            router_logits_partials = None
        topk_kwargs = (
            {"input_ids": input_ids_global}
            if getattr(self, "is_hash", False)
            else {}
        )
        if router_logits_partials is not None:
            topk_kwargs["router_logits_partials"] = router_logits_partials
        if use_vision_topk:
            # lever RE5: the fused top-k + E5 when stock would prune, else stock vision_topk
            # lever RT: eager EXTEND: stock's compiled router kernel launched directly (route_e5.route otherwise)
            topk_output = rt.route(
                self,
                router_logits,
                input_ids_global,
                num_token_non_padded,
            )
        else:
            topk_output = self.topk(
                hidden_states,
                router_logits,
                num_token_non_padded=num_token_non_padded,
                expert_location_dispatch_info=dispatch_info,
                **topk_kwargs,
            )
    else:
        pre_quant_input = None
        shared_output = None
        topk_output = self.topk.empty_topk_output(
            hidden_states.device, layer_id=self.layer_id
        )

    # lever RE5: stock prune_topk, except on the output route_e5.route pruned already
    # lever RT: eager EXTEND (no E5 prune in flight): after_topk's unchanged return taken directly
    topk_output = rt.after_topk(self, topk_output)
    if self._fuse_shared_experts_inside_sbo and not skip_shared_experts:
        shared_output = None

        def _pre_combine_hook(
            dispatcher: BaseDispatcher, combine_input: CombineInput
        ):
            nonlocal shared_output
            self.alt_stream.wait_stream(torch.cuda.current_stream())
            with torch.cuda.stream(self.alt_stream):
                shared_output = self._forward_shared_experts(
                    hidden_states, gemm_output_zero_allocator
                )

            pre_combine_hook_handle.remove()

        def _post_combine_hook(
            dispatcher: BaseDispatcher, hidden_states: torch.Tensor
        ):
            nonlocal shared_output
            torch.cuda.current_stream().wait_stream(self.alt_stream)
            post_combine_hook_handle.remove()

        pre_combine_hook_handle = self.experts.dispatcher.register_pre_combine_hook(
            _pre_combine_hook
        )
        post_combine_hook_handle = (
            self.experts.dispatcher.register_post_combine_hook(_post_combine_hook)
        )

    if pre_quant_input is not None:
        final_hidden_states = self.experts(
            hidden_states,
            topk_output,
            pre_quant_input=pre_quant_input,
        )
    else:
        final_hidden_states = self.experts(
            hidden_states,
            topk_output,
        )
    if (
        not _is_cuda
        and not _is_musa
        and not _is_xpu
        and not _use_aiter
        or isinstance(self.experts.quant_method, KTEPWrapperMethod)
    ):
        # fused in biased_grouped_topk so we can skip here
        final_hidden_states *= self.routed_scaling_factor

    if (
        defer_shared
        and hidden_states.shape[0] > 0
        and not self._fuse_shared_experts_inside_sbo
        and not skip_shared_experts
    ):
        shared_output = self._forward_shared_experts(
            hidden_states,
            gemm_output_zero_allocator,
            pre_quant_input=pre_quant_input,
        )

    if return_moe_output:
        return MoEOutput(
            routed=final_hidden_states,
            shared=shared_output,
            experts=self.experts,
            routed_scaling_factor=self.routed_scaling_factor,
            shared_is_replicated=self._shared_expert_tp1,
        )

    final_hidden_states = maybe_fuse_routed_scale_and_shared_add(
        self.experts,
        final_hidden_states,
        None if self._shared_expert_tp1 else shared_output,
        self.routed_scaling_factor,
    )
    # lever FG: the post-experts all-reduce runs eagerly between FG's two graphs (fg.ffn); FG's layers have
    # reduce_results set and no replicated (TP1) shared expert (fg._bind_layer)
    return final_hidden_states


def fg_gate(self, hidden_states, gemm_output_zero_allocator=None):
    """lever FG: forward_normal's own router-gate call (the eager reference of FG's static-buffer gate)."""
    return rt.gate(self, hidden_states, gemm_output_zero_allocator)
